SEC='BAŞLANGIÇ'
def add(title,message,notes,layout='cards',cards=(),sources=(),question=None,**kw):
    d=dict(title=title,message=message,notes=notes,layout=layout,cards=cards,section=SEC,sources=sources,**kw)
    if question:d['question']=question
    SLIDES.append(d)
def photo(t,m,img,c,n,**kw):add(t,m,n,'photo',c,image=img,**kw)
def compare(t,m,imgs,c,n,**kw):add(t,m,n,'compare',c,images=imgs,**kw)
def cards(t,m,c,n,**kw):add(t,m,n,'cards',c,**kw)
def flow(t,m,c,n,**kw):add(t,m,n,'flow',c,**kw)
def table(t,m,h,r,n,**kw):add(t,m,n,'table',headers=h,rows=r,**kw)
def diagram(t,m,k,c,n,**kw):add(t,m,n,'diagram',c,diagram=k,**kw)
def full(t,m,img,n,**kw):add(t,m,n,'full',image=img,**kw)
def code(t,m,cmd,c,n,**kw):add(t,m,n,'code',c,code=cmd,**kw)

add('AUTO Görevler','Uçuşu ArduPilot yürütür; görüntülerden anlamı biz üretiriz.',
    'İlk haftada araç, kontrol ve simülasyon bileşenlerini tanıdık. Bu hafta aynı düzeni gerçek iş akışlarına dönüştüreceğiz. Önce aracın ve kameranın davranışını göreceğiz; sonra tarla ilaçlama, 2D tarla haritalama, bina çevresinde 3D veri toplama ve sabit kanatla hareket gözlemini uygulayacağız. Tüm sahneler gerçek Gazebo kayıtlarıdır. Görevler önceden hazırlanmış, uçurulmuş ve inişle doğrulanmıştır. Önerilen ders: anlatım80, canlı uygulama30, değerlendirme10 dakika.',layout='cover')
cards('Bugün neyi yapabiliyor olacağız?','Bir görevi planlayıp uçuracak, çıktısını ölçerek değerlendireceğiz.',[
 ('Planla','NAV, DO, kamera tetiği ve ROI ile AUTO görevi kur.'),('Uygula','Aynı görevi simülasyonda kalkıştan inişe izle.'),('Değerlendir','Kaplama, fotoğraf, nokta bulutu ve olay kaydını yorumla.')],
 'Öğrenciden yalnız ekranı izlemek yerine üç kanıt istemek yararlıdır: görev dosyası, uçuşun tamamlandığını gösteren kayıt ve uygulama ürünü. Haritada çizginin görünmesi görev başarısı için yeterli değildir. Kamera tetik sayısı, tarlanın kaplanması veya hareket olayının kaydedilmesi ayrı kontrol edilir. Her örnekte önce beklenen sonucu söyleyin, sonra simülasyonu açın ve son olarak beklenen ile ölçülen sonucu karşılaştırın.',question='İHA rotayı tamamladı ama fotoğraf yoksa haritalama görevi başarılı mıdır?')
compare('İlk haftadan bu haftaya','Kurulu simülasyon artık bir iş problemini çözmek için kullanılacak.',
 ['iris_yakin.png','mapping_dunya.png'],[('1. hafta: sistem','Araç · uçuş yazılımı · simülatör · yer istasyonu'),('2. hafta: görev','Rota · faydalı yük · veri · ölçülebilir sonuç')],
 'İlk haftanın native Windows kurulumunu koruyoruz. Bu haftanın ek dosyaları kamera kaydı, sahne nesneleri ve görüntü işleme içindir. Öğrencinin bileşenler arasındaki ilişkiyi hatırlamasını sağlayın: Gazebo fizik ve görüntü üretir, SITL uçuşu yönetir, Mission Planner görevi yükler. Bu hafta başarı ölçütleri bir üst düzeye çıkar: uçmak dışında işe yarayan veri elde etmek de gerekir.',sources=['gazebo'])
table('Dört uygulama, dört farklı çıktı','Aynı AUTO mantığı farklı sektör problemlerine uygulanabilir.',
 ['Problem','AUTO içinde yapılan','Uygulama çıktısı'],[
 ['Tarla ilaçlama','Grid + şeritlerde pompa','İdeal kaplama haritası'],['2D tarla haritalama','Grid + mesafeli kamera tetiği','Düzlem projeksiyonlu mozaik'],['3D bina haritalama','İki orbit + ROI + kamera tetiği','Seyrek 3D nokta bulutu'],['Kırsal hareket gözlemi','Kalkış + sabit tarama + iniş','Olay görüntüsü ve kırpım']],
 'Bunlar sektörde kullanılan görev planlama yaklaşımlarının öğretim örnekleridir. İlaçlama için iş genişliği ve pompa zamanlaması; haritalama için örtüşme; bina için çoklu bakış ve kamera yönelimi; gözetim için hareketli kameradan gelen verinin ayrıştırılması önemlidir. Ürünlerin kapsamı farklıdır: mozaik DEM değildir, seyrek bulut yoğun model değildir, hareket adayı insan sınıfı değildir. Bu ayrımları her uygulamanın sonunda yeniden göstereceğiz.')
flow('Komut kimden, veri kimden geliyor?','Uçuş kontrol döngüsü ArduPilot içinde kalır.',[
 ('Mission Planner','Görevi araca yaz'),('ArduPilot SITL','AUTO görevini yürüt'),('Gazebo','Fizik ve RGB üret'),('Python','Kaydet, işle, raporla')],
 'Buradaki oklar öğretim amaçlı iş akışını gösterir; fizik ile uçuş yazılımı sürekli çift yönlü etkileşir. Kritik sınır şudur: görüntü işçileri konum veya hız setpointi göndermez. Öğrenci uçuş sırasında Python kodundan yörünge değiştirmeyi beklememelidir. Yer istasyonu görevi yükledikten sonra NAV ve DO komutları uçuş yazılımında yürütülür. Uygulama dosyalarını hazırlayan Python da yer görev planlayıcısıdır; uçuşta araç sürmez.',sources=['auto','gazebo'])
cards('AUTO modunun sınırını koruyalım','Rota ve faydalı yük görevde; görüntü analizi ayrı süreçte.',[
 ('ArduPilot','Kalkış, waypoint, hız, kamera, ROI, pompa, iniş.'),('Python','RGB kaydı, mozaik, eşleştirme, hareket olayı.'),('Bu haftanın kontrolü','Uçuş boyunca AUTO; uçuş setpointi sayısı sıfır.')],
 'Öğretmen test aracı görev dosyasını yükler, normal arm ve mission start gönderir; öğrencinin menüsünde aynı işlemleri Mission Planner operatörü yapar. Pasif gözlemci hiçbir uçuş komutu göndermez. Kamera yönelimi ArduPilot mount servo çıkışlarından gelir. Görüntü analizinde olay bulunması rotayı değiştirmez. Böylece öğrenciler bir görevin AUTO ile nereye kadar çözüldüğünü, görüntü işlemenin hangi aşamada ek değer sağladığını ayırt edebilir.',sources=['auto'])
table('Doğrulanan ortak ortam','Bu haftanın ölçümleri aynı sürümlerle, native Windows üzerinde alındı.',
 ['Bileşen','Referans','Görevi'],[
 ['Gazebo','Jetty 10.5.0','Fizik, 3D dünya ve kameralar'],['ArduCopter / ArduPlane','4.7.2 / 4.7.2','AUTO uçuş yazılımı'],['Yer istasyonu','Mission Planner · TCP5760','Görev yükleme ve başlatma'],['Görüntü işleme','OpenCV + NumPy + SciPy','Mozaik, 3D eşleştirme, hareket'],['Ders eklentisi','Yerel kaynak koddan derleme','RGB kayıt, ideal gimbal ve sahne']],
 'Bu haftanın uçuş testleri bu bilgisayardaki Windows düzeninde yapılmıştır. Dünya ve model kaynakları taşınabilirdir; Linux üzerinde bu haftanın başlatıcısı test edilmiş gibi sunulmaz. İlk haftanın Linux rehberi ayrı durur. Sürüm karışmasını önlemek için indirmeler SHA256 ile denetlenir. Öğrenciye hazır EXE veya ZIP dağıtmıyoruz; ilk haftadaki ortamın üzerine kaynaklar yerelde hazırlanır.',sources=['windows','gazebo'])

SEC='ARAÇ VE KAMERA'
photo('Önce aracı tanıyalım','Iris modeli fiziksel olarak uçar; sahnede konumu zorla taşınmaz.',
 'iris_yakin.png',[('Platform','Dört rotorlu Iris · QUAD/X'),('Kontrol','ArduCopter SITL → motorlar'),('Gözlem','Kamera ve servo çıkışları')],
 'Gerçek Gazebo yakın planında pervaneleri, gövdeyi, iniş ayaklarını ve gölgeyi gösterin. Bu örnek bir ticari araç teknik föyü değildir. İtki ve uçuş hareketi ilk haftadaki ArduPilot Gazebo modelinden gelir. Ders eklentisi uçağın veya quadrotorun pozunu ayarlamaz; sadece bağımsız kamera, ilaçlama görselleştirmesi ve yürüyen insanlar gibi sahne nesnelerini yönetir. Dolayısıyla görev hataları gerçek SITL davranışında görünür.',question='Araç fiziği yerine pozunu doğrudan değiştirsek hangi uçuş hatalarını göremeyiz?')
photo('Dünya, araç ve kamera farklı katmanlardır','Gördüğümüz manzara ile uçuş telemetrisi birlikte okunmalı.',
 'intro_dunya.png',[('Dünya','Tarla, yollar, bina, ağaçlar'),('Araç','GPS konumu ve göreli irtifa'),('Kamera','FOV, yönelim, çözünürlük')],
 'Öğrenciye geniş görünüş ile araç kamerasını ayırt ettirin. Geniş görünüş sunum için sahneyi gösteren ikinci kameradır; haritalama ve hareket işçileri aracın RGB kamerasını kullanır. Görüş değişikliği her zaman aracın hareket ettiği anlamına gelmez: gimbal dönebilir. Aynı şekilde araç sabitken kamera yönelimi değiştiğinde görüntüdeki tüm zemin hareket eder. Bu ilişki son uygulamadaki hareket telafisinin temelidir.')
diagram('Sahnede koordinatlar nasıl okunuyor?','Yerel ENU ile GPS ve irtifa referansını karıştırmayın.',
 'coordinates',[('Yerel dünya','x: Doğu · y: Kuzey · z: Yukarı'),('Home','−35.363262 / 149.165237'),('İrtifa','Home AMSL584m; görevler göreli')],
 'Sanal dünyamız SITL’nin varsayılan home koordinatına bağlanır; Canberra uydu haritasındaki gerçek yapıları temsil etmez. Mission Planner haritasında tarlanın görsel olarak görünmemesi görev dosyasının bozuk olduğu anlamına gelmez. Görev waypoint irtifaları home’a göredir; home’un584m deniz seviyesi irtifasıyla toplanmamalıdır. Bina ROI hedefi de bu dosyada home’a göre7m seçilmiştir. ENU dünyasında kuzey pozitif y yönüdür.')
photo('Kamera ne üretiyor?','Her RGB kareye zaman, kalibrasyon ve gerçek kamera pozu eşlik eder.',
 'mapping_kamera.png',[('Quadrotor RGB','960 × 640 · yatay70°'),('Kayıt','Simülasyon ve duvar saati'),('Geometri','Kamera konumu ve yönelimi')],
 'Kamera sensörü saniyede6 görüntü üretir; kayıt köprüsü yaklaşık3 kare/saniye saklar. Görev tetiği olduğunda en yakın gerçek RGB kare seçilir. Ekrandaki görüntü bir yer dokusu kopyası değil Gazebo kamerasının kaydıdır: bitkiler, gölgeler ve perspektif içerir. Kalibrasyon dosyasında çözünürlük ve yatay FOV saklanır. Bu bilgiler sonraki düzlem projeksiyonu ve üçgenleme için kullanılır; gerçek kamerada ayrıca lens ve zaman kalibrasyonu gerekir.')
diagram('İrtifa ve FOV, görülen alanı belirler','18m irtifada yatay görüntü genişliği yaklaşık25,2m olur.',
 'fov',[('Yatay FOV','70°'),('Ayak izi','25,2 × 16,8m · düz zemin'),('Nominal GSD','Yaklaşık2,6cm / piksel')],
 'Düz zemine dik bakan kamerada genişlik W=2H tan(FOV/2) bağıntısıyla bulunur.18m ve70derece için25,2m genişlik elde edilir.960piksele böldüğümüzde yaklaşık2,6cm/piksel nominal yer örnekleme aralığı çıkar. Bu bir doğruluk garantisi değildir; gimbal eğimi, yükselti, hareket bulanıklığı ve kalibrasyon hatası sonucu etkiler. Dikey boyut görüntü oranıyla16,8m olur. Sabit kanatta kamera eğik olduğu için bu basit dik-bakış hesabını aynen kullanmayacağız.',question='İrtifayı iki katına çıkarınca ayak izi ve GSD nasıl değişir?')
compare('Aynı araç, farklı kamera açısı','Gimbal açısı görüntünün kapsamını değiştirir.',
 ['kamera_90.png','kamera_20.png'],[('−90°: nadir','Haritalama için zemine dik bakış'),('−20°: ileriye eğik','Daha uzak alan; güçlü perspektif')],
 'Bu kareler aynı8m AUTO tanıtım uçuşundan seçilmiştir. Önce−90derecede kalkış alanına, sonra−45ve−20derecede ileriye bakılır. Sunumdaki iki kareyi karşılaştırın; ara açı kaydı kamera_45.png dosyasında mevcuttur. Kamera öne döndüğünde ufuk ve tarla görünüme girer. Aracın yatay rotası değişmeden görüntünün değişebildiğini vurgulayın. Geometrik hesaplarda araç yaw değeri tek başına kamera yönünü vermez.')
table('Kamera yönü ArduPilot’tan geliyor','İdeal gimbal, gerçek mount servo çıkışlarını izler.',
 ['İşlev','ArduPilot ayarı','Ders sahnesindeki karşılığı'],[
 ['Servo mount','MNT1_TYPE = 1','İdeal üç eksenli gimbal'],['Roll','SERVO9_FUNCTION = 8','Kamera yatış açısı'],['Pitch','SERVO10_FUNCTION = 7','Nadir / eğik bakış'],['Yaw','SERVO11_FUNCTION = 6','ROI yönüne dönüş'],['Fotoğraf','SERVO13_FUNCTION = 10','Kamera komutunun çıkışı']],
 'Mount servo PWM değerleri Gazebo eklentisine aktarılır ve kamera modelinin yönelimini belirler. Bu dersin gimbali ideal kinematik modeldir; fiziksel atalet, gecikme, kablo sınırı veya titreşim modellenmez. ROI başarısını değerlendirirken bu varsayım önemlidir. Mission Planner’ın eski Camera Gimbal ekranındaki alanlar sürüme göre farklı olabilir; gerekli ayarları Full Parameter Tree üzerinden görüp anlamlarını tartışın. Öğrencinin bu haftada ayarları ezbere değiştirmesi gerekmez.',sources=['mount','roi'])
table('Tanıtım görevini satır satır okuyalım','AUTO içinde kamera açısını değiştirip bekletebiliyoruz.',
 ['Sıra','Komut','Beklenen davranış'],[
 ['1','TAKEOFF · 8m','Home üzerinde yüksel'],['2–3','MOUNT_CONTROL · −90° + LOITER','Nadir görüntüyü8s gözle'],['4–5','MOUNT_CONTROL · −45° + LOITER','Eğik görüntüyü8s gözle'],['6–7','MOUNT_CONTROL · −20° + LOITER','İleri bakışı8s gözle'],['8–9','Nadir konum + LAND','Kamerayı sıfırla ve in']],
 '00_kamera_tanitimi.waypoints dosyasını Mission Planner’a yükleyin. HOME satırı da sayıldığında dosyada10görev öğesi bulunur. MOUNT_CONTROL açı komutu ile LOITER_TIME bekleme ayrı öğelerdir. Kamera yönü değişsin diye GUIDED moda geçmiyoruz. Öğrenciden görüntünün bekleme anında sabitlenmesini ve inişte motorların durmasını izlemesini isteyin. Araç kamerası ile geniş sahne görüntüsünü sırayla gösterin.',sources=['commands'])
photo('Tanıtım uçuşu da ölçüldü','8m yükselme, kamera beklemeleri ve home’a iniş tamamlandı.',
 'intro_ucus.png',[('Uçuş modu','Silahlıyken yalnız AUTO'),('En yüksek irtifa','8,00m'),('Operatör deneyi','Pasif gözlemci:0 uçuş komutu')],
 'Bu test iki TCP bağlantısını da doğruladı. Operatör bağlantısı5760üzerinden görevi yükleyip normal arm ve mission start gönderdi;5762üzerindeki gözlemci yalnız kayıt aldı. Uçuş çizgisinin yatayda nokta görünmesi doğaldır: tanıtımda araç home üzerinde yükselir. Sağ grafik göreli irtifayı gösterir. Kamera açısı değişirken uçuş modu değişmez. Bu kayıt menünün pasif çalışma mantığı için kanıt olarak saklanmıştır.')

SEC='GÖREVİ HAZIRLAMA'
flow('Öğrencinin başlangıç adımları','İlk haftanın kurulumu üzerine iki başlatıcı yeterlidir.',[
 ('Güncelle','VS Code → Git Pull'),('Hazırla','simulasyon / Kur.cmd'),('Dünyayı aç','Baslat.cmd → uygulama'),('Bağlan','TCP127.0.0.1:5760')],
 'Depoyu ilk hafta klonlayan öğrenci VS Code üzerinden güncellemeyi alabilir. haftalar/02/simulasyon altındaki Kur.cmd bir kez çalıştırılır; resmî indirmeler hash kontrolünden geçer ve eklenti yerelde derlenir. Sonraki derslerde Baslat.cmd yeterlidir. Önceki simülasyon oturumunu kapatın; aynı portta ikinci SITL açmayın. Kurulumun başarı mesajı gelmeden uçuşa geçilmez. Sıfırdan ayrı öğrenci Python ortamında kurulum ve tekrar çalıştırma denenmiştir.',sources=['repo'])
flow('Mission Planner’dan görevi uçuralım','Görev dosyasını araca yazın; sensörler hazırken AUTO ve ARM seçin.',[
 ('Dosyayı aç','Plan → görev dosyası'),('Araca yaz','Write WPs / Görevi yaz'),('Hazır ol','GPS + EKF + pre-arm'),('Başlat','AUTO → ARM')],
 'Bu haftanın simülasyon parametreleri AUTO modunda normal arm ve kalkışa izin verir. Bu ayar gerçek araç için genel bir tavsiye değildir. Plan ekranında doğru uygulamanın waypoint dosyasını açın ve Write WPs ile araca yazın. Haritada görünmesi yazıldığı anlamına gelmez. Sensör hazır mesajını bekleyin, AUTO seçin ve ARM edin; dosyalar TAKEOFF ile başlar. Başlatıcı uçuş komutu göndermez. Mission Planner SIMULATION sekmesinden ikinci bir SITL başlatılmamalıdır.',sources=['auto','plan'])
table('NAV, DO ve CONDITION ne yapar?','Komut türünü bilmek, zamanlama hatalarını önler.',
 ['Tür','Görevi','Bu haftadan örnek'],[
 ['NAV','Nereye gidileceğini / beklemeyi belirler','TAKEOFF · WAYPOINT · LAND'],['DO','Bir işlevi çalıştırır','Kamera tetiği · ROI · pompa'],['CONDITION','DO komutuna koşul getirir','Mesafe veya gecikme koşulu'],['Önemli davranış','NAV ilerleyişi DO zamanlamasını etkiler','Sonraki NAV’a geçişte DO atlanabilir']],
 'ArduPilot NAV komutlarını ve bunlara bağlı DO/CONDITION komutlarını görev motorunda yürütür. DO komutunu yalnız dosyadaki görsel sıraya bakarak yorumlamak yerine aktif NAV bacağını düşünmek gerekir. Koşulun tamamlanmasından önce sonraki NAV’a geçilirse ilgili DO atlanabilir. Her uygulamada gerçek servo çıkışı veya kamera geri bildirimi kontrol edilir. Özellikle şerit başlangıcına yerleştirilen pompa aç komutu ile dönüşte kapatma komutu arasında doğru ilişki kurulmalıdır.',sources=['commands'])
cards('Bir zamanlama hatasını nasıl düzelttik?','Şerit başındaki DO komutunu gereksiz mesafe koşuluyla geciktirmeyin.',[
 ('İlk deneme','Başlangıç WP → CONDITION_DISTANCE → pompa aç.'),('Gözlenen sorun','Koşul, sonraki WP’ye yaklaşmayı bekledi; şerit geç kaldı.'),('Çalışan düzen','Başlangıç WP → pompa aç → bitiş WP → pompa kapat.')],
 'İlk denemede CONDITION_DISTANCE komutu sezgisel olarak şerit başına yakınlığı ifade edecek sanıldı. Oysa aktif hedef bir sonraki NAV noktası olduğunda mesafe koşulu bitiş noktasına yaklaşana kadar pompayı bekletti. Kayıtlardaki pompa PWM’i bunu ortaya çıkardı. Bu örnekte koşulu kaldırdık ve şerit başlangıcından sonraki DO komutunu ilgili bacakta hemen uyguladık. Ders: görev listesi tek başına kanıt değildir; gerçekleşen çıkış zamanını ölçün.',sources=['commands'],question='Pompa şerit sonunda açılıyorsa ilk bakılacak yer neresi olur?')
table('Sürümle birlikte parametre adları da değişir','4.7.2’de gerçek parametre listesine göre çalışıyoruz.',
 ['Amaç','Bu sürümde kullanılan','Birim / not'],[
 ['Waypoint hızı','WP_SPD','m/s'],['Yatay ivme','WP_ACC','m/s²'],['Waypoint kabul yarıçapı','WP_RADIUS_M','m'],['RTL irtifası','RTL_ALT_M','m'],['Tanıtımda normal LAND','PLND_ENABLED = 0','Precision landing aranmaz']],
 'Eski eğitimlerde görülen WPNAV_SPEED ve santimetre temelli değerleri bu sürümde aynen kopyalamayın. Bu haftanın parametre dosyaları gerçek4.7.2parametre geri okumasına göre hazırlandı. Varsayılan Iris dosyasında precision landing açık olduğunda beacon beklenebildi; sıradan LAND öğretmek için bu haftada kapatıldı. Öğrenciden parametre ismi ile fiziksel birimini birlikte okumasını isteyin. İlgili ayarlar yalnız bu haftanın ayrı SITL çalışma klasörüne uygulanır.')

SEC='UYGULAMA 1 · TARLA İLAÇLAMA'
photo('Problem: tarlayı eşit işlemek','Rota yalnız alanı dolaşmamalı; iş genişliğiyle alanı kaplamalı.',
 'spray_dunya.png',[('İş alanı','62 × 48m tarla'),('Görev','Paralel şeritlerde işleme'),('Dönüş','Pompa kapalı')],
 'Tarla sınırını ve baş-son dönüş alanını geniş görüntüde gösterin. Tarım uygulamasında çizginin tarlanın ortasından geçmesi tüm alanın işlendiğini göstermez. Her uçuş çizgisinin belirli bir etkili çalışma genişliği vardır. Gerçek sistemde bu genişlik nozul, yükseklik ve rüzgâr gibi etkenlerle kalibre edilir; burada8m ideal geometrik genişlik kullanıyoruz. Önce planlanan alanı, sonra şeritlerin kapsadığı alanı kıyaslayacağız.',sources=['spray'])
photo('Aynı dünya iki göreve hizmet ediyor','Tarla nesneleri hem ilaçlama hem kamera uygulaması için hazır.',
 'mapping_dunya.png',[('3D varlıklar','Bitki sıraları, traktör, depo'),('Çevre','Ahır, ağaçlar, yol ve çit'),('Başlangıç','Ayrı ve açık kalkış alanı')],
 'Tarla dokusu tek başına düz bir resim değildir; yapraklı ve gövdeli bitkiler3Dolarak yer alır. Bu nesneler gölge ve perspektif üretir, haritalamada gerçek görüntü eşleşmesini anlamlı kılar. Tarla dışındaki ağaç ve binalar görsel bağlam sağlar. Kalkış alanı tarladan ayrı konumdadır. İlaçlama ile2Dharitalama görevleri aynı dünya dosyasını kullanır; yalnız uçuş yüksekliği, şerit aralığı ve faydalı yük komutları değişir.')
table('Aynı tarla, farklı görev geometrisi','İş genişliği ile kamera ayak izi aynı şey değildir.',
 ['Özellik','İlaçlama','2D haritalama'],[
 ['İrtifa','4m','18m'],['Hız','3m/s','4m/s'],['Şerit sayısı / aralığı','9 / 7m','7 / 8m'],['Faydalı yük','DO_AUX_FUNCTION → sprayer','DO_SET_CAM_TRIGG_DIST →4m'],['Başarı kontrolü','İdeal kaplama + pompa zamanlaması','Fotoğraf sayısı + görüntü örtüşmesi']],
 'Bu değerler test edilmiş öğretim dünyasına aittir. İlaçlamada kamera yerine ideal iş şeridi genişliğini kullanıyoruz. Haritalamada ise FOV, irtifa ve örtüşme belirleyici. Öğrencilere aynı grid dosyasını iki uygulamada değiştirmeden kullanmanın neden doğru olmayacağını sorun. İlaçlama dönüşlerinde pompa kapalıdır. Haritalama kamera tetiği dönüşler sırasında da açık kalabilir; ürün üretirken tüm kareler bilinen pozlarla değerlendirilir.')
diagram('Grid planında kenarlar da önemlidir','7m aralık, 8m ideal iş genişliğiyle güvenli örtüşme sağlar.',
 'spray_grid',[('İlaçlama planı','9 şerit · 7m aralık'),('İş genişliği','8m ideal geometrik şerit'),('Baş / son','Tarla sınırını aşan uç noktalar')],
 'Bu şema grid kavramını anlatır; gerçek ilaçlama görevinde9şerit vardır.7m aralık ile ideal8m genişlik arasında1m nominal örtüşme bulunur. Uç noktaları y17ve69m seçilerek y19–67m arasındaki tarla sınırları aşılır. Waypoint dönüşü ve kabul yarıçapı nedeniyle gerçek uçuş çizgisi köşeleri kesebilir; sadece ideal çizimleri değil kaydedilmiş izlerden hesaplanan kaplamayı kontrol ediyoruz. Kenar kaçırma hatasını sonraki sonuç karşılaştırmasında göreceğiz.')
table('İlaçlama görevinin tekrarlanan bloğu','Her şerit: başlangıç → aç → bitiş → kapat.',
 ['Adım','AUTO komutu','Değer / davranış'],[
 ['Başlat','TAKEOFF + DO_CHANGE_SPEED','4m · 3m/s'],['Şeride gir','NAV_WAYPOINT','Şerit başı'],['İşle','DO_AUX_FUNCTION','15 · HIGH(2) → sprayer açık'],['Şeridi tamamla','NAV_WAYPOINT','Şerit sonu'],['Dön ve bitir','LOW(0) · sonraki şerit · LAND','Dönüşte pompa kapalı']],
 '01_tarla_ilaclama dosyası home dahil41öğeden oluşur. DO_AUX_FUNCTION komutunda15sprayer işlevini seçer;2yüksek konum,0düşük konumdur. SERVO12_FUNCTION22pompa çıkışını sağlar.9şeridin her birinde aç-kapa çifti bulunur. Araç eve geri dönüp LAND ile görevi bitirir. Öğrencinin uygulamadan önce dosyada9aç ve9kapat komutunu bulmasını isteyin. Sonraki slaytta gerçekten uygulanan PWM’i inceleyeceğiz.',sources=['spray','commands'])
cards('Pompa komutunu fiziksel çıkıştan ayıralım','Görev komutu, servo çıkışı ve görselleştirme üç ayrı kanıttır.',[
 ('Görev işlevi','DO_AUX_FUNCTION15: sprayer aç / kapat.'),('ArduPilot çıkışı','SERVO12_FUNCTION22: pompa PWM’i.'),('Gazebo görünüşü','PWM açıkken ideal püskürtme işaretleri.')],
 'Sahnede görülen tanecikler gerçek akışkan simülasyonu değildir. Gerçek ArduPilot sprayer çıkışının açık olduğunu anlaşılır biçimde gösterir. Pompanın elektriksel PWM’i litre/dakika ölçümü sağlamaz. Bu yüzden dersin kaplama ürünü gerçek araç izi ve pompa açık süresinden8m ideal şerit çizerek hesaplanır. Gerçek uygulamada akış sensörü, pompa-nozul kalibrasyonu ve saha doğrulaması gerekir; bunlar bu geometrik öğretim modelinin dışında kalır.',sources=['spray'])
photo('Dokuz şeritte pompa açılıp kapandı','Pompa PWM kaydı, DO komutlarının çalıştığını gösteriyor.',
 'pompa_pwm.png',[('Açık bloklar','9 ayrı çalışma bölümü'),('Dönüşler','PWM düşük → işleme kapalı'),('Toplam açık süre','Yaklaşık157s')],
 'Grafikte zaman yatayda, mikrosaniye cinsinden PWM düşeyde gösterilir. Yüksek bölgeleri sayın ve görevdeki9şeritle eşleştirin. Şeritler arası dönüşte çıkış kapanır. Toplam157s civarı süre, telemetrinin örnekleme sıklığına dayalıdır; kimyasal tüketimi ölçmez. İlk denemelerdeki görev zamanlaması hatası bu grafikten görülebiliyordu. Bu nedenle bir komutun Mission Planner listesinde görünmesiyle yetinmiyoruz.',question='Dokuz şerit için sekiz açık blok görseydik hangi verileri karşılaştırırdık?')
photo('Alçak irtifada bitkiler belirginleşiyor','İlaçlama uçuşu 4m ve 3m/s ile AUTO içinde gerçekleşti.',
 'spray_kamera.png',[('Gerçek RGB','Yapraklar, gövdeler, gölgeler'),('Uçuş','Yalnız AUTO · normal arm'),('Bitiş','Home üzerinde LAND')],
 'Kamera burada haritalama ürünü için değil uçuş bağlamını göstermek için kullanılıyor. Düşük irtifada tek tek bitkiler görünür; aynı kamera18mde daha geniş alanı kapsar. İlaçlama görevini başlatıp ilk şerit, dönüş ve ikinci şeritte pompa davranışını izletin. Görsel damlacık işaretleri ile gerçek PWM kaydının tutarlı olduğunu gösterin. Fiziksel rotor akımı veya damlacık birikimi ölçtüğümüz izlenimini vermeyin.')
compare('Test ettik, grid sınırlarını düzelttik','İdeal kaplama %82,86’dan %100’e çıktı.',
 ['ilaclama_once.png','ilaclama_sonra.png'],[('İlk deneme:7 şerit','Kenarlar ve uç bölgeler eksik kaldı.'),('Son deneme:9 şerit','7m aralık; baş-son uzatması; %13,86 örtüşme.')],
 'Her iki görüntü de gerçek uçuş izleri ve gerçek pompa açık sinyalinden hesaplandı. Lacivert dikdörtgen hedef tarladır; yeşil en az bir geçiş, sarı birden fazla geçiş, açık alan işlenmeyen bölgedir. İlk görev uçuşu başarıyla bitirse de tarla kaplaması82,86yüzdeydi.9şerit ve uzatılmış uç noktalarla tekrar uçulduğunda hedef alanın tamamı ideal8m genişlikte kaplandı. Bu sonuç damlacık kalitesi veya gerçek doz homojenliği değildir.')
cards('Doz hesabında hız neden önemli?','PWM yüzdesi tek başına litre/hektar vermez.',[
 ('Bağıntı','Q = D × V × W /600'),('Sayısal örnek','20L/ha ×10,8km/h ×8m /600 =2,88L/dk'),('Gerekli ölçüm','Gerçek debi ve etkili iş genişliği kalibre edilir.')],
 'Bu slayt bir birim dönüşümü ve mühendislik hesabı örneğidir; ürün veya kimyasal kullanım önerisi değildir. Hektar başına hedef hacim D, km/saat cinsinden hız V, metre cinsinden genişlik W ile litre/dakika Q hesaplanır.3m/s hız10,8km/saat eder. Pompa PWM’i ile gerçek debi arasındaki ilişki bilinmeden bu örnek dozun uygulandığı söylenemez. Simülasyonda kanıtlanan şey komut zamanlaması ve ideal alan kaplamasıdır.')
cards('Uygulama: bir şeridi değiştirin','Önce tahmin edin, sonra gerçek izden kaplamayı kontrol edin.',[
 ('Değiştir','Şerit aralığını artır; ayrı görev dosyasına kaydet.'),('Gözle','Dönüşte pompanın kapandığını doğrula.'),('Karşılaştır','Kaplama yüzdesi ve örtüşme nasıl değişti?')],
 'Öğrencilerden orijinal dosyayı koruyarak görev kopyası hazırlamalarını isteyin. İlk çalışmada yalnız bir değişkeni değiştirin. Aynı uçuş bitiş şartını koruyun: AUTO tamamlanmış, araç inmiş ve disarm olmuş olmalı. Ardından raporun kaplama ve örtüşme değerlerini karşılaştırın. Şerit sayısını azaltmanın uçuş süresini düşürürken kenar boşluklarını artırabileceğini tartışın. Ürün kalitesi ile rota süresi arasında açık bir mühendislik tercihi vardır.')

SEC='UYGULAMA 2 · 2D TARLA HARİTALAMA'
photo('Problem: tarlanın tek görüntüsünü üretmek','Birbirini örten fotoğraflar toplayıp ortak düzleme taşıyoruz.',
 'mapping_dunya.png',[('Uçuş','18m · 4m/s'),('Grid','7 şerit · 8m aralık'),('Kamera','Her4m’de bir görev tetiği')],
 'Aynı tarla dünyasında bu kez yükseklik ve şerit aralığı kamera geometrisine göre seçilir. İlaçlama göreviyle karıştırmamak için doğru dosyayı araca yazdırın. Görevin hedefi tüm alanı yeterli örtüşmeyle fotoğraflamaktır. Bu derste kamera pozlarını simülatörden bilerek düz zemin varsayımında mozaik üretiyoruz. Gerçek saha fotogrametrisinde poz kestirimi ve yükselti modeli gibi ek aşamalar gerekir; sonuç türünü baştan doğru adlandıralım.',sources=['grid'])
cards('GSD, çıktı pikseli ve doğruluk farklıdır','2,6cm nominal GSD, 2,6cm konum doğruluğu demek değildir.',[
 ('Kamera örneklemesi','18m: yaklaşık2,6cm/piksel.'),('Mozaik rasteri','12piksel/m →8,33cm/piksel.'),('Konumsal doğruluk','Bu çalışmada gerçek saha hatası ölçülmedi.')],
 'GSD bir pikselin ideal zeminde kapladığı mesafedir. Mozaik rasterini daha kaba seçmemiz hesap yükünü azaltır; görüntü çözünürlüğü ile son raster boyutu birbirinden bağımsız seçimlerdir. Konumsal doğruluk ise kontrol noktalarıyla ölçülmesi gereken başka bir kavramdır. Bilinen simülatör pozları gerçek dünyada GNSS veya fotogrametriyle elde edilmek zorundadır. Öğrencinin yalnız piksel boyutuna bakıp santimetre hassasiyet iddiasında bulunmamasını sağlayın.')
diagram('İleri ve yanal örtüşme birlikte planlanır','8m hat aralığı ve4m tetik aralığı, geniş ortak alan sağlar.',
 'grid',[('Yanal örtüşme','1 −8/25,2 ≈ %68'),('İleri örtüşme','1 −4/16,8 ≈ %76'),('Varsayım','Dik bakış · düz zemin ·18m')],
 'Nominal kameranın genişliği25,2m, uçuş yönündeki yüksekliği16,8m kabul edilir. Şerit aralığı8m olduğunda yanal, tetik mesafesi4m olduğunda ileri örtüşme hesaplanır. Gövde ve gimbal yönelimi gerçek ayak izini değiştirebilir; bu yüzden ürünün gerçek kaplama sayacı ayrıca ölçülür. Şemadaki noktalar mesafe tetiklerini temsil eder. Dönüşlerde de tetik açık kalabildiği için fotoğraf sayısı yalnız düz çizgi uzunluğundan hesaplanan sayıya eşit olmayabilir.',sources=['grid'])
flow('Mission Planner’da otomatik grid üretimi','Survey(Grid) kamera komutlarını da ekleyebilir.',[
 ('Alanı çiz','Draw Polygon → köşeler'),('Grid oluştur','Auto WP → Survey(Grid)'),('Kamerayı tanıt','FOV / sensör / odak + örtüşme'),('Kontrol et','Rota + yükseklik + DO tetiği')],
 'Ders dosyası çalışan referanstır; öğrenciler bu akışı kullanarak alternatif grid oluşturabilir. Kamera için sanal eşdeğer sensör genişliği6,4mm ve odak4,57mm yaklaşık70derece yatay FOV verir; bu gerçek bir ürün teknik özelliği değildir.960x640çözünürlüğü ve18m irtifayı girin, örtüşmeleri yakın değerlerde seçin. Survey(Grid) kamera komutlarını ekleyebilir; Simple Grid aynı kamera işlevini otomatik sağlamaz. Son görevde trigger başlatma ve durdurmayı mutlaka okuyun.',sources=['grid','plan'])
table('Haritalama görevinde hangi öğeler var?','Grid uçuşu ve kamera tetikleme aynı AUTO görevinde yer alır.',
 ['Bölüm','Komut','Bu derste değer'],[
 ['Yüksel / hız','TAKEOFF · DO_CHANGE_SPEED','18m ·4m/s'],['İlk şerit','NAV_WAYPOINT','Grid başlangıcı'],['Çekime başla','DO_SET_CAM_TRIGG_DIST','4m'],['Alanı tara','NAV_WAYPOINT × şeritler','7 şerit ·8m aralık'],['Bitir','Tetik0 · dönüş · LAND','Home üzerinde iniş']],
 '02_tarla_2d_haritalama dosyası home dahil21öğedir. İlk şerit başlangıcından sonra tetik açılır; son şerit tamamlandığında0ile kapatılır. ArduPilot gidilen mesafeye göre kamera komutu üretir; Python zamanlayıcıyla fotoğraf isteği göndermiyor. Uçuş süresi veya hız değişse de mesafeli tetik mantığı korunur. Kamera gerçekten görüntü verdi mi sorusu ayrıca kayıtlardan cevaplanmalıdır.',sources=['commands','grid'])
cards('Mesafeli tetik zamanlayıcı değildir','DO_SET_CAM_TRIGG_DIST: hareket mesafesine bağlı fotoğraf komutu.',[
 ('4m','Bu görevde çekim mesafesi.'),('0m','Mesafeli çekimi durdur.'),('CAMERA_FEEDBACK','Bu ayarda yazılımsal tetik geri bildirimi.')],
 'CAM1_TYPE1servo kamera ve CAM1_FEEDBAK_PIN−1kullanılıyor. Bu nedenle CAMERA_FEEDBACK mesajı fiziksel hot-shoe veya gerçek pozlama teyidi değildir; yazılımsal kamera komutunun geri bildirimidir. RGB köprüsü en yakın gerçek Gazebo karesini seçer. Gerçek kamerada shutter gecikmesi, exposure zaman damgası ve geri bildirim kablosu gibi konular ayrıca çözülür. Mesafeli çekim kavramını bu ayrımı gizlemeden öğretin.',sources=['commands','grid'])
flow('Tetik ile görüntüyü nasıl eşleştiriyoruz?','Tetik geri bildirimi ile gerçek RGB kaydı ayrı zaman kaynaklarıdır.',[
 ('ArduPilot','CAMERA_FEEDBACK'),('RGB köprüsü','Gerçek kare + kamera pozu'),('Eşleştirme','En yakın duvar saati'),('Kontrol','81tetik →81fotoğraf')],
 'Final uçuşunda81tetik mesajı81gerçek Gazebo fotoğrafıyla eşleşti. En büyük duvar saati farkı yaklaşık0,394s idi. Ürün üretirken tetik anındaki varsayımsal poz yerine seçilen görüntünün kendi simülasyon kamera pozu kullanıldı. Böylece geometrik hesap görüntünün gerçek anına bağlıdır. Bu yöntem gerçek bir donanım zaman senkronizasyonu çözümü olarak sunulmaz. Öğrencilerden fotoğraf sayısı ile tetik sayısının neden ayrı kontrol edildiğini açıklamalarını isteyin.')
photo('Uçuş kaydı, planlanan grid’i doğruluyor','Araç 18m’de şeritleri tamamlayıp home’a indi.',
 'mapping_ucus.png',[('Mod','Silahlıyken yalnız AUTO'),('En yüksek irtifa','18,01m'),('Fotoğraf','81gerçek RGB kare')],
 'Soldaki iz gerçek telemetriden üretilmiştir; plan çizimi değildir. Şerit başındaki ivmelenme ve dönüşlerin köşeleri yumuşattığını gösterin. Sağdaki grafik kalkış, iş irtifası ve iniş evrelerini ayırır. Bu uçuşta normal arm öncesi bir hazır olma tekrar isteği oldu; force-arm kullanılmadı. Güncel başlatıcı gerçek pre-arm sağlık durumunu bekler. Araç inişten sonra disarm oldu; yalnız son waypoint’e gelmek tamamlanma ölçütü değildir.')
photo('Tek fotoğrafta hangi bilgiler var?','Bitki sıraları, parallax ve gölgeler gerçek kamera görüntüsündedir.',
 'mapping_kamera.png',[('Örtüşme','Komşu karelerle ortak bitkiler'),('Yükselti','Bitkiler düzlem üstünde'),('Zorluk','Tekrarlı desen ve gölge')],
 'Fotoğrafı büyütüp bitki sıralarının tekrar eden yapısını gösterin. Tekrarlı desenler görüntü eşleştirmesini zorlaştırabilir. Düzlem projeksiyonunda zeminin z0olduğunu varsayıyoruz; bitki tepeleri ve diğer yükseltiler bu varsayıma uymaz, küçük çiftlenme veya dikiş hataları oluşturabilir. Görüntüyü gerçek RGB sensöründen almanın avantajı bu sınırlamaları görünür kılmasıdır. Yer dokusunu doğrudan son ürüne kopyalamıyoruz.')
flow('Mozaik üretiminin dört adımı','Kamera ışınlarını z=0 düzlemine projekte ediyoruz.',[
 ('Kalibrasyon','Piksel → kamera ışını'),('Poz','Kamera ışını → dünya'),('Düzlem','z=0kesişimini bul'),('Birleştir','Ortak rasterde harmanla')],
 'Bu akış bilinen kamera iç parametreleri ve simülatör pozlarına dayalıdır. Her görüntünün zemin köşeleri bulunur, düzleme dönüşümü hesaplanır ve ortak rasterde birleştirilir. Kaynak zemin dokusu okunmaz; sadece uçuşta çekilmiş fotoğraflar kullanılır. Gerçek ortofoto iş akışındaki yükseklik modeli ve poz optimizasyonu burada yoktur. Dersin amacı uçuş planı ile fotoğraf geometrisi ve ürün kaplaması arasındaki bağı göstermektir.',sources=['triangulate','sfm'])
full('Sonuç: aynı tarlanın tek mozaik görüntüsü','81fotoğraftan912×744piksel düzlem mozaiği üretildi.',
 'tarla_mozaik.png',
 'Bu görüntü final uçuşunun ürünüdür. Sıraların sürekliliğini, tarla sınırını ve kenar dikişlerini birlikte inceleyin. Raster8,33cm/piksel olarak seçildi. Kareler gerçek kamera pozlarına göre projekte edildiği için bu çalışma bilinen pozlu mozaik olarak adlandırılır. Bitkiler zemin düzleminden yüksek olduğu için yer yer dikiş etkileri görülebilir. Öğrencilerden hem başarılı alanı hem de varsayımın zayıf kaldığı bölgeyi göstermelerini isteyin.')
cards('Haritalama sonucunu nasıl puanlarız?','Görüntünün güzel görünmesi yanında kaplama da ölçülmeli.',[
 ('Alan kaplama','Hedef tarla: %100.'),('Çoklu gözlem','En az3görüntüyle kaplanan alan: %99,53.'),('Sınır','Ölçülen saha konum doğruluğu veya DEM yok.')],
 'Kaplama metrikleri gerçek fotoğraf ayak izlerinin hedef alan üzerinde sayılmasıyla hesaplandı. En az üç görüntüyle kaplanan alan99,53yüzdedir. Bu metrik görüntü eşleşmesinin her noktada başarılı olduğu veya konumun gerçek dünyada doğru olduğu anlamına gelmez. Öğrencinin nicel bir ölçüyü doğru kapsamda yorumlamasını isteyin. Aynı zamanda az fotoğrafın her zaman verimlilik olmadığını; yeterli örtüşmenin ürün güvenilirliği için gerekli olduğunu tartışın.')
code('Uygulama: mozaik üretin ve karşılaştırın','Komutu kendi haritalama uçuşunuzun klasörüyle çalıştırın.',
 '.\\.local\\venv\\Scripts\\python.exe .\\tools\\mosaic_2d.py\n  "UCUS_KLASORU"',
 [('Girdi','Uçuşun photo_manifest.json ve RGB fotoğrafları.'),('Çıktı','products/tarla_mozaik.png + mosaic_metrics.json')],
 'Komut sunumda okunabilirlik için iki satıra ayrılmıştır; terminalde tek satır yazılır. Komutları haftalar/02/simulasyon klasöründe çalıştırın. UCUS_KLASORU yerine başlatıcının RESULT mesajında gösterilen flight.json dosyasının bulunduğu klasörü yazın. Görev kopyasında tetik aralığını değiştirin ve tekrar uçun. Fotoğraf sayısı, kaplama, örtüşme ve görünür dikişleri karşılaştırın. Çalışmayan bir çıktıyı yalnız daha yüksek çözünürlük seçerek düzeltmeye çalışmayın.')

SEC='UYGULAMA 3 · BİNA ÇEVRESİNDE 3D VERİ'
photo('Problem: binayı birden çok açıdan görmek','Tek bir nadir görüntü cephelerin 3D yapısını vermez.',
 'building_dunya.png',[('Sahne','14 ×12 ×14m ana bina'),('Gereksinim','Cephelerde ortak detaylar'),('Görev','İki yükseklikte çevresel çekim')],
 'Bina modelinde dört farklı cephe dokusu, pencereler, giriş gölgeliği, kolonlar ve çatı ekipmanları vardır. Bu ayrıntılar hem görsel olarak anlaşılır bir sahne hem de SIFT için eşleşebilir yüzey sağlar. Tek bir üstten görüntü cephe derinliğini yeterince gözleyemez. Birden fazla yönden ve iki yükseklikten bakarak görüş çeşitliliği toplarız. Son ürünün seyrek nokta bulutu olduğunu baştan söyleyin; yoğun, dokulu bir bina mesh’i vaat etmiyoruz.')
photo('Cephe ayrıntıları neden gerekli?','Tekrarlı ve düz yüzeylerde güvenilir eşleşme bulmak zorlaşır.',
 'building_kamera.png',[('Doku','Tuğla ve pencere çerçeveleri'),('3D ayrıntı','Gölgeliğe ait parallax'),('Çevre','Araç, ağaç ve yollar')],
 'Dört cephedeki farklı dokular tamamen benzer pencerelerin yanlış eşleşme riskini azaltmaya yardımcı olur. Yine de pencere tekrarları ve gölgeler hatalı eşleşme üretebilir. Kaynak bina mesh’i rekonstrüksiyon scriptine verilmez. Eşleşmeler gerçek RGB görüntülerden bulunur. Doğrulama aşamasında ana cephe sınırlarına mesafe gibi ölçüler hesaplanabilir; bunlar simülasyon değerlendirmesidir, kaynak geometriyi ürün diye kopyalamak değildir.')
diagram('İki AUTO orbit, tek sabit ROI','Araç yörüngede ilerlerken kamera bina merkezine yönelir.',
 'orbit',[('Yarıçap','26m'),('İrtifalar','18m ve23m'),('ROI','Bina merkezi · göreli7m')],
 'Orbit,24açısal aralıklı waypoint’lerden oluşan kapalı yol olarak hazırlanmıştır; sürekli matematiksel circle kontrolü değildir. Her turda başlangıç noktasına geri dönülür ve ikinci yükseklikte tekrar edilir. ArduPilot mount sistemi ROI hedefini izlerken araç NAV noktalarını yürütür. Böylece Python ile kameraya her karede açı komutu göndermek gerekmez. İdeal gimbalın fiziksel gecikme ve atalet modellemediğini yeniden hatırlatın.',sources=['roi','commands'])
table('Bina görevinin yapısı','ROI ve mesafeli tetik, orbit waypoint’leri boyunca sürer.',
 ['Bölüm','Komut','Değer'],[
 ['Yüksel / hız','TAKEOFF · DO_CHANGE_SPEED','18m ·3m/s'],['Hedefi seç','DO_SET_ROI','(0,45,7)m yerel hedef'],['Çekimi başlat','DO_SET_CAM_TRIGG_DIST','3m'],['Orbitler','NAV_WAYPOINT dizisi','26m yarıçap ·18/23m'],['Bitir','Tetik0 · dönüş · LAND','Home üzerinde iniş']],
 '03_bina_3d_haritalama dosyasında home dahil58öğe bulunur. ROI konumu GPS koordinatlarına dönüştürülmüştür; yükseklik home’a göre7m olarak tanımlanır. Görev listesini açıp ROI’nin orbitlerden önce geldiğini, tetik kapatmanın iki turdan sonra olduğunu gösterin. ArduPilot kamera yönü ve uçuş konumu için ayrı görevleri aynı anda yürütebilir. Uçağın yaw yönünün her zaman kamera hedef doğrultusuna eşit olması gerekmez.',sources=['commands','roi'])
cards('ROI, “binaya bak” komutudur','Kamera yönelimi uçuş rotasından bağımsız bir görev işlevi olabilir.',[
 ('Hedef konumu','Bina merkezindeki sabit3D nokta.'),('ArduPilot mount','Hedef doğrultusuna gereken açıları üretir.'),('İdeal gimbal','Gerçek servo PWM’ini kamera pozuna uygular.')],
 'Hedef doğrultusu araç hareket ettikçe değişir. ArduPilot bunu mount çıkışlarında günceller; Python yörünge veya gimbal takip döngüsü kurmaz. Gimbal açısal sınırları ROI’nin görülebilmesini kısıtlayabilir. Bu dünyada kamera ideal ve görüş şartları uygundur. Gerçek sistemde kablo dönüş sınırı, mekanik tıkanma, gecikme ve titreşim gibi konular ayrıca test edilmelidir. Öğrenciye kamera yönü ile gövde yönünün farklı olabileceğini gerçek karelerle gösterin.',sources=['mount','roi'])
photo('Orbit gerçekten uçuldu; yönelim de ölçüldü','ROI doğrultu hatasının %95’i0,724° altında kaldı.',
 'building_ucus.png',[('Uçuş','İki tur ·18/23m · AUTO'),('ROI medyan hata','0,318°'),('ROI %95 değeri','0,724° · ideal gimbal')],
 'Hata, kaydedilmiş kamera ileri ekseni ile aynı andaki kamera konumundan ROI noktasına giden vektör arasındaki açıdır. Örnekler orbit bölgesinde filtrelenmiştir. Bu değerler gerçek gimbal donanım doğruluğu olarak yorumlanmaz; ideal kinematik mount modelinin doğru bağlandığını gösterir. Sol grafikte iki tur üst üste geldiği için tek daireye yakın görünür; sağdaki irtifa iki yüksekliği açıkça gösterir.')
photo('Binaya sürekli yönelmiş kamera','Araç orbitin farklı noktasındayken bina görüntüde kalır.',
 'building_kamera.png',[('Bakış','Cephe ve çatı birlikte'),('Ortak ayrıntı','Komşu karelerde aynı pencere'),('Tetik','Her3m’de bir fotoğraf komutu')],
 'Bu kare gerçek orbit uçuşundan alınmıştır. Binanın ortada kalması tek başına tüm cephenin yeterli örtüşmeyle görüldüğü anlamına gelmez; tur boyunca görüş açılarına bakmak gerekir. Giriş gölgeliği veya yakındaki ağaçlar bazı yüzeyleri örtebilir. Kameranın binaya baktığını doğruladıktan sonra fotoğraf sayısını ve eşleştirme sonuçlarını inceleyin. Binanın kaynak modelinin görüntüde görünmesi, nokta bulutunun kaynaktan kopyalandığı anlamına gelmez.')
cards('108 görüntü, tek başına 3D model değildir','Fotoğraflar arasında aynı ayrıntıları güvenilir biçimde bulmalıyız.',[
 ('Veri','108gerçek tetik fotoğrafı.'),('Seçim','Yakın görüş çiftleri karşılaştırılır.'),('Geometri','Kalibrasyon + bilinen kamera pozları kullanılır.')],
 'Her fotoğrafın diğer107fotoğrafla karşılaştırılması gereksiz iş yüküdür. Script görünüm yakınlığına göre aday çiftler seçer ve141çift üzerinde eşleşme değerlendirir. SIFT ayrıntı noktaları bulunur, tanımlayıcı eşleşmeleri oran testiyle süzülür ve geometrik tutarsızlıklar RANSAC ile ayıklanır. Sonra eşleşen pikseller bilinen kamera pozlarıyla üçgenlenir. Bu ders tam Structure from Motion yerine onun görüntü eşleştirme ve3Dgeometri bölümünü öğretir.',sources=['triangulate','sfm'])
full('SIFT: iki karede aynı ayrıntıyı bulmak','Renkli çizgiler, süzülmüş görüntü eşleşmelerini gösterir.',
 'sift.png',
 'Görsel scriptin gerçek eşleştirme çıktısıdır. Bazı çizgilerin benzer pencereler arasında yanlış gitme ihtimalini tartışın. SIFT sonrası Lowe oran testi0,72, temel matris RANSAC ve daha sonra yeniden izdüşüm filtresi uygulanır. Bu aşamaların her biri farklı bir tutarsızlığı azaltır, sıfır hata garantisi sağlamaz. Çok sayıda eşleşme çizgisi iyi modelin tek ölçütü değildir; geometri ve yeniden izdüşüm hatası da incelenir.',sources=['triangulate'])
flow('Eşleşen piksellerden 3D noktaya','İki kamera ışını ortak bir dünya noktasını sınırlar.',[
 ('SIFT','Ayrıntı ve tanımlayıcı'),('Süz','Oran testi + RANSAC'),('Üçgenle','K ve bilinen pozlar'),('Temizle','Pozitif derinlik + hata')],
 'İki görüntüde aynı fiziksel noktayı gözlediğimizi varsayarsak, kamera kalibrasyonu ve pozları piksel ışınlarını dünya koordinatlarına taşır. Gürültü nedeniyle ışınlar kusursuz kesişmez; üçgenleme en uygun3Dnoktayı bulur. Negatif derinlikli noktalar,2pikselden büyük yeniden izdüşüm hataları ve ilgisiz bölge noktaları ayıklanır.8cmvoxel ile yinelenen noktalar seyreltilir. Bina mesh’i bu hesapta okunmaz.',sources=['triangulate'])
full('Sonuç: görüntülerden seyrek bina bulutu','1787nokta üretildi; cephe ve çatı yapısı seçilebiliyor.',
 'bina_3d.png',
 'Bu grafik son PLY dosyasındaki1787noktanın görünüşüdür. Binanın dikey yüzeyleri ve çatı üstü ayrıntıları kabaca seçilir; eksik bölgeler ve aykırı noktalar da görünür. Çıktı yoğun mesh veya dokulu model değildir. Bilinen simülatör kamera pozları ölçeği sağlar. Analitik ana yüzeylere medyan mesafe yaklaşık7,3cm olsa da bu yalnız ideal dünyadaki değerlendirmedir; gerçek saha doğruluğu iddiası değildir. Öğrencilerden bulutun hangi kısımlarının gözlenemediğini göstermelerini isteyin.')
cards('Bu örnek hangi fotogrametri aşamasıdır?','Seyrek üçgenleme yaptık; tam SfM ve yoğun rekonstrüksiyon yapmadık.',[
 ('Yaptık','RGB → eşleşme → bilinen pozla seyrek3D.'),('Bu örnekte yok','Poz kestirimi, bundle adjustment, yoğun mesh.'),('Sonraki adım','Aynı fotoğrafları tam SfM aracında karşılaştır.')],
 'Tam Structure from Motion akışı kamera pozlarını görüntülerden kestirir ve birlikte optimize eder. Biz pozları simülatörden alarak temel geometriyi görünür kıldık. COLMAP gibi araçlar seyrek model sonrası dense reconstruction da sağlayabilir; bunlar bu haftanın çalışır temel örneğinin dışında tutulur. Öğrencinin PLY dosyası ile dokulu mesh arasındaki farkı ve ölçeğin nereden geldiğini açıklayabilmesi beklenir.1787nokta bir başarı metrikidir ama tek başına kaliteli model garantisi değildir.',sources=['sfm'])
code('Uygulama: bina bulutunu üretin','Çıktıyı görüntülerden yeniden üretebiliriz.',
 '.\\.local\\venv\\Scripts\\python.exe .\\tools\\reconstruct_3d.py\n  "UCUS_KLASORU"',
 [('Girdi','Bina uçuşunun fotoğrafları ve kamera pozları.'),('Çıktı','products/bina_seyrek_nokta_bulutu.ply + PNG grafikler')],
 'Komut terminalde tek satır yazılır. Yalnız bina uygulamasının uçuş klasörünü kullanın. Script gerçek RGB fotoğraflarını işler; kaynak bina model dosyasını okumaz. Çalışma süresi bilgisayara göre birkaç dakika olabilir. Sonuç klasöründe eşleşme görseli, rekonstrüksiyon metriği ve PLY dosyası oluşur. Bir3Dgörüntüleyicide bulutu açıp farklı açılardan incelemek, tek sabit grafikte görünmeyen aykırı noktaları fark etmeyi sağlar.')
cards('Uygulama: bakış çeşitliliğini sınayın','Fotoğraf sayısını değil, gözlenen yüzeyleri de karşılaştırın.',[
 ('Tek tur','İlk yüksekliği kullanarak ürün çıkar.'),('İki tur','18m ve23m verisini birlikte kullan.'),('Yorumla','Çatı, cephe ve kapalı bölgeler nasıl değişiyor?')],
 'Bu karşılaştırma için görev veya fotoğraf listesinin bir kopyasını kullanın. Kameranın aynı noktadan çok sayıda benzer görüntü çekmesinin yeni geometri sağlamayabileceğini tartışın. Yükseklik ve açı değişimi görüş çeşitliliği sağlar; çok büyük açı farkı ise eşleştirmeyi zorlaştırabilir. Yalnız toplam nokta sayısını değil binanın yüzeylerinin gözlenmesini, aykırı noktaları ve yeniden izdüşüm filtresini değerlendirin. Kamera her iki turda da ROI’ye bakmalıdır.')

SEC='UYGULAMA 4 · SABİT KANATLA HAREKET GÖZLEMİ'
photo('Problem: uçuş sürerken hareketi kaydetmek','Sabit tarama görevi değişmeden, görüntüden olay çıktısı alıyoruz.',
 'plane_dunya.png',[('Platform','Zephyr sabit kanat'),('Görev','AUTO kalkış → tarama → iniş'),('Algılama','Hareketli insan adayını kaydet')],
 'Kırsal alanda önceden belirlenmiş bir tarama rotası düşünün. Uçak rota üzerinde kalırken görüntü işçisi hareket adayını bulur, çerçeveli görüntü ve kırpım üretir. Görev hedefe yönelmez, takip veya kovalamaya dönüşmez. Bu ayrım AUTO sınırını korumak için bilinçli seçildi. Hedefler simülasyondaki yürüyen üç insandır; öğrenilecek esas problem, hareketli kamerada arka plan hareketini ayırmaktır.')
photo('Kırsal sahne ve hareketli insanlar','Pist, tepeler, evler, ağaçlar ve üç yürüyen kişi hazır.',
 'plane_dunya.png',[('Sahne','Pist ve geniş kırsal alan'),('Hedefler','Farklı renkli kıyafetli3kişi'),('Hareket','Sahne içinde sürekli yürüyüş')],
 'Sahne nesneleri gerçek3Dvarlıklardır. İnsan modelleri simülasyon zamanına bağlı hareket eder ve gerçek RGB görüntüde konum değiştirir. Konumları değerlendirme için saklanır, detektörün insanı bulmasına verilmez. Tepeler ve ağaçlar homografi varsayımını zorlayarak parallax üretir. Bu özellik yanlış alarmları tartışmak için yararlıdır. Pist ve sürekli zemin çarpışması otomatik kalkış ve iniş testleriyle geliştirilmiştir.')
photo('Sabit kanatta kamera seçimi farklı','1280×800 ve55° aşağı eğim, hedefi görüntüde daha kullanışlı kıldı.',
 'hareket_ham.png',[('RGB','1280 ×800 · yatay70°'),('Bakış','İleriye eğik ·55° aşağı'),('Tarama irtifası','Göreli55m')],
 'İlk denemede nadir ve daha geniş görüşlü kamera, insanları çok az piksele indirdi; hareket analizi güvenilir olay üretmedi. Çözünürlük ve bakış açısı bu sahnede tekrar test edilerek güncellendi. Bu kamera tercihi her görev için optimum değildir; eğik bakışta perspektif ve mesafeye göre ölçek değişir. Hedefin kaç piksele düştüğü algılama yönteminin çalışabilirliğini doğrudan etkiler. Bu nedenle detektör ayarından önce kamera geometrisini kontrol ediyoruz.')
table('Sabit kanat görevinin tamamı AUTO','Kalkış ve iniş de görev dosyasında yer alıyor.',
 ['Bölüm','Öğeler','Amaç'],[
 ['Kalkış','TAKEOFF + hız17m/s','Pistten havalan ve55m’ye çık'],['Tarama','NAV3,4,6,8','Üç sabit tarama bacağı'],['Dönüşler','NAV5,7 + çıkış9','Rota bağlantıları'],['İnişe hazırlık','Downwind + DO_LAND_START','İniş bölümünü işaretle'],['Yaklaşma / iniş','60m →30m → LAND','Önceden tanımlı son yaklaşma']],
 '04_sabit_kanat_gozetim dosyası home dahil15öğedir. Tarama etiketleri görüntü işçisi için salt-okunur görev fazı bilgisi sağlar. DO_LAND_START iniş bölümünü tanımlar; LAND komutu gerçek inişi yürütür. RTL_AUTOLAND2bu örneğin parametreleri arasındadır ancak normal başarılı görev akışı zaten LAND’e kadar ilerler. Görüntü işçisi herhangi bir yeni waypoint veya mod değişikliği göndermez.',sources=['takeoff','land','landstart'])
cards('AUTO kalkış için yer koşulları da önemlidir','Çalışan uçuş yalnız havadaki rotadan ibaret değildir.',[
 ('İlk sorun','Gövde temasında uzun ve kararsız yer koşusu.'),('Sahne düzeltmesi','Düşük sürtünmeli ideal iniş takımı temasları.'),('Doğrulama','Normal arm → AUTO kalkış → görev irtifası.')],
 'Zephyr referans modelinde pistten kalkış için ideal teker temasları eklendi; uçak pozuyla zorla havaya kaldırılmadı. TKOFF_ROTATE_SPD0ve LAND_PITCH_DEG5bu test edilmiş rüzgârsız referans modelin ayarlarıdır. ARSPD_TYPE0nedeniyle fiziksel hava hız sensörü yoktur. Bu değerler gerçek bir hava aracına doğrudan uygulanacak ayar önerileri değildir. Burada öğrenci AUTO kalkış komutunun fizik, pist ve doğru konfigürasyonla birlikte çalıştığını görmelidir.',sources=['takeoff'])
photo('Gerçek uçuş: sabit rota ve iniş yaklaşması','Uçuş boyunca mod AUTO kaldı; görüntü analizi rotayı değiştirmedi.',
 'plane_ucus.png',[('Tarama','Önceden yazılmış üç bacak'),('En yüksek irtifa','60,08m'),('Sonuç','LAND ve disarm tamamlandı')],
 'Sol grafik gerçek GPS telemetrisinden üretilmiştir. Dönüşlerin waypoint noktalarını birleştiren keskin çizgiler olmadığını, uçuş dinamiğinin ve dönüş sınırlarının izde görüldüğünü gösterin. Sağda tarama yüksekliği ve iniş yaklaşması seçilebilir. Silahlı uçuş sırasında kaydedilmiş mod yalnız10yani Plane AUTO’dur. Uçuş kontrolüne konum veya hız setpointi gönderilmemiştir. Bu kayıt, hedef görüldüğünde uçuşun sürdüğünü gösterecek olay zaman çizelgesiyle birlikte okunur.')
diagram('AUTO iniş: yaklaşma geometrisi','İniş hedefi tek başına yeterli değildir; öncesinde uygun yaklaşma gerekir.',
 'landing',[('Ön yaklaşma','450m geride ·60m'),('Son yaklaşma','240m geride ·30m'),('LAND sonucu','Hedefe4,11m yatay uzaklık')],
 'Şema ölçekli bir uçuş grafiği değildir; gerçek görevdeki yaklaşma noktalarını açıklar.30mden240mde iniş yaklaşık7,1derece geometrik eğimdir. Gerçek araçta rüzgâr, stall hızı, flare ve pist uzunluğu önemli olur. Bu örnekte ideal rüzgârsız dünya kullanılır. Otomatik inişin tamamlandığını yalnız düşük irtifadan değil disarm olayından da doğruladık. Hedefe4,11mson yatay mesafe bu tek testin sonucudur; hassas iniş garantisi değildir.',sources=['land','landstart'])
full('Gazebo arayüzünde çalışan sahne','Son canlı uçuşta Gazebo GUI, SITL ve görüntü işçisi birlikte çalıştı.',
 'gazebo_arayuz.png',
 'Bu ekran görüntüsü gerçek native Gazebo Sim penceresinden alınmıştır. Solda sahne görünüşü, sağda model listesi ve araç bileşenleri görülür. Arayüz görüntüsü bir arka plan illüstrasyonu değildir. Aynı oturumda kamera kayıtları ve canlı hareket işçisi çalıştı. Sunumdaki diğer sahne fotoğrafları ise arayüzsüz kamera sensörünün gerçek RGB çıktılarıdır. Öğrenciler Gazebo görünüşünü değiştirirken araç kamerasının kalibrasyonunu değiştirmediklerini bilmelidir.')
compare('Hareketli kamerada her şey hareket eder','İki kare farkı tek başına hareketli insanı ayıramaz.',
 ['hareket_ham.png','hareket_artik.png'],[('Gerçek kamera karesi','Uçuş ve kamera dönüşü tüm sahneyi kaydırır.'),('Telafi sonrası artık','Arka plan hizalandıktan sonra kalan değişim.')],
 'Bir sabit kamerada basit arka plan çıkarma işe yarayabilir; uçan kamerada ise sabit zemin bile görüntü üzerinde yer değiştirir. Önce baskın zemin hareketini kestirip önceki kareyi güncel kareye hizalarız. Sonra kalan farkı eşikleriz. Siyah-beyaz artık maskesinde insan dışında gölge, ağaç parallax’ı veya hizalama hatası da görülebilir. Bu yüzden tek karedeki parlak leke olay için yeterli değildir.',sources=['homography'])
flow('Hareket adayını nasıl buluyoruz?','Görüntü işçisi yalnız RGB ve salt-okunur uçuş fazını kullanır.',[
 ('ORB','Arka plan ayrıntılarını eşleştir'),('RANSAC','Zemin homografisini kestir'),('Artık fark','Hizalı kareleri karşılaştır'),('Süreklilik','Birden çok karede doğrula')],
 'ORB tanımlayıcıları Hamming mesafesi ve0,74oran testiyle eşleştirilir. Homografi2,5piksel RANSAC eşiği ve en az0,5içerdeş oranıyla kabul edilir. Artık maske küçük bileşenlere ayrılır; en az iki gözlem ve yaklaşık1,2piksel bağımsız hareket aranır. Olaylar çok sık yinelenmesin diye aynı iz için iki saniyelik çıktı aralığı uygulanır. Bunlar sahneye göre test edilmiş başlangıç değerleridir; genellenmiş bir insan algılayıcısı değildir.',sources=['orb','homography'])
cards('Homografi hangi varsayımla çalışıyor?','Baskın zemin tek düzlem gibi görünürse kamera hareketi telafi edilebilir.',[
 ('İyi koşul','Yeterli ayrıntı ve büyük ortak zemin alanı.'),('Zor koşul','Tepe, yakın ağaç, gölge ve keskin dönüş.'),('Sonuç','Parallax artık hareket olarak kalabilir.')],
 'Homografi iki görüntüdeki tek düzlem arasındaki izdüşümsel ilişkiyi açıklar. Kırsal sahnede zemin büyük alan kaplasa da ağaç tepeleri ve binalar farklı derinliktedir. Uçak hareket ettikçe bu nesneler zemine göre farklı kayar; tek homografi hepsini hizalayamaz. Yanlış alarm örneğini daha sonra özellikle göstereceğiz. Detektörün sınırlarını bilmek, yalnız doğru kutuyu göstermekten daha öğreticidir.',sources=['homography'])
cards('İlk görüntü işleme denemesi neden zayıftı?','Düşük kontrastlı çimende yeterli eşleşme bulunmuyordu.',[
 ('İlk ayar','ORB FAST eşiği9: zayıf zemin ayrıntısı.'),('İyileştirme','FAST3: daha fazla kullanılabilir eşleşme.'),('Kontrol','Aynı gerçek kayıtta hizalama ve olaylar tekrar incelendi.')],
 'Kamerayı iyileştirdikten sonra bile ilk detektör düşük kontrastlı çimende homografi kuracak yeterli ORB ayrıntısını bulamadı. FAST eşiğini3e düşürmek bu sahnede kullanılabilir eşleşmeleri artırdı. Örnek bir çiftte661eşleşme ve yaklaşık95yüzde içerdeş elde edildi. Eşiği düşürmek her zaman daha iyi değildir; gürültü de artabilir. Değişikliği aynı görüntülerde yeniden çalıştırıp hem doğru olayları hem yanlış alarmları karşılaştırdık.',sources=['orb'])
table('Görüntü analizi yalnız tarama fazında','Görev fazı bilgisi görüntü analizini sınırlar; uçuşu yönetmez.',
 ['Faz','Görev indeksi','İşçinin davranışı'],[
 ['Tarama','3,4,6,8','RGB hareket analizi açık'],['Dönüş / transit','5,7,9 ve diğerleri','Yeni olay analizi kapalı'],['İrtifa koşulu','ArduPilot göreli irtifa ≥25m','Kalkış/iniş görüntüsünü ele'],['Bilgi yönü','Telemetri → işçi','Uçuşa komut gönderilmez']],
 'Önce tüm uçuşu işlemek dönüş ve transit sırasında parallax kaynaklı çok sayıda yanlış alarm üretti. Sabit görevin SCAN etiketlerini salt-okunur analiz fazı olarak kullanınca bu gereksiz alarmlar azaldı. Bu bir detektör doğruluk hilesi değil uygulamanın kapsamını açık seçmektir: görev tarama bacaklarında gözlem yapar. Hedef konumları detektöre verilmez. En güncel kod irtifayı simülatör pozundan değil ArduPilot telemetrisinden okur.')
photo('Canlı denemeden gerçek olay çıktısı','Yeşil kutu bir hareket adayıdır; uçak AUTO uçuşuna devam eder.',
 'hareket.png',[('Kaynak anı','Simülasyon36,022s'),('Uçuş bilgisi','AUTO10 · görev indeksi3'),('Kayıt','Tam kare + kırpım + olay JSON')],
 'Bu olay uçuş devam ederken canlı işçi tarafından üretildi. Çıktıdaki kutu görüntü tabanlı adaydır; değerlendirme katmanı daha sonra gerçek simülasyon kişi kutusuyla kesiştiğini doğruladı. İlk olayın hesaplanma gecikmesi bu örnekte yaklaşık0,77sduvar saatidir. Bu değer tek olay örneğidir, gecikme garantisi değildir. Uçuşta yeni hedef waypoint’i veya GUIDED komutu gönderilmedi. Tam kareyi bağlam için, kırpımı ayrıntı için birlikte gösterin.')
compare('Olayın ayrıntısı ve hareket artığı','Küçük hedefler birkaç piksel olduğunda yorum dikkat ister.',
 ['hareket_kirpim.png','hareket_artik.png'],[('Kaydedilen kırpım','Gerçek RGB’den büyütülmüş küçük hedef.'),('Artık maske','Hizalama sonrası değişimin yeri.')],
 'Kırpım sunumda büyütülmüştür; yeni ayrıntı üretilmemiştir. Bu çözünürlükte insanın görünmesi hareketi insan sınıfı olarak tanıdığımız anlamına gelmez. İşçi genel hareket adayları bulur. Simülasyon kişi koordinatları yalnız değerlendirmede kullanılır. Dolayısıyla renkli giysi veya küçük siluet bu örnekte yorumlamayı kolaylaştırsa da genellenmiş kişi algılama performansı iddia edilmez. Gerçek saha için farklı görüntü ölçeklerinde ve sahnelerde ayrıca değerlendirme gerekir.')
cards('Canlı uçuşun sayısal sonucu','23olay üretildi;19’u bağımsız kişi kutusuyla örtüştü.',[
 ('23 olay','Aynı kişi birden çok olaya yol açabilir.'),('19 örtüşme','Yalnız sonradan simülasyon gerçeğiyle ilişkilendirildi.'),('4 yanlış alarm','İnsan sınıflandırıcısı veya benchmark sonucu değildir.')],
 'Bu sayılar tek canlı uçuşun olay sayılarıdır;23farklı kişi ya da genel precision/recall anlamına gelmez. Değerlendirmede küçük ve dolgulu kırpımlar için IoU0,06üstü ilişkilendirme kullanıldı. Aynı kişiden tekrar olay gelebilir; kaçırılan tüm insan anları etiketlenmediği için recall hesaplanmıyor. Detektör insan koordinatlarını giriş olarak kullanmaz. Bu kapsamı açıkça söylemek sonuçları karşılaştırılabilir ve dürüst tutar.')
photo('Yanlış alarmı da inceleyelim','Ağaç ve parallax, insan olmasa da hareket artığı üretebilir.',
 'yanlis_alarm.png',[('Örnek','Ağaç bölgesindeki hareket adayı'),('Neden','Derinlik farkı ve hizalama artığı'),('Ders','Bir kutu, sınıf veya kesin karar değildir.')],
 'Bu görsel aynı final canlı uçuşta üretilen dört yanlış alarmdan biridir. Ağaç zemin düzleminden yukarıda olduğundan kamera hareketi sonrası aynı homografiyle tam hizalanmaz. Kalan hareket süreklilik filtresini aşabilir. Örnek yalnız başarılı olayları seçmenin sistemi olduğundan iyi göstereceğini hatırlatır. Gerçek uygulamada insan sınıflandırıcısı, daha güçlü hareket modeli veya ek doğrulama katmanı gerekebilir; bu haftada ana hedef AUTO uçuşu değiştirmeden görsel olay üretmektir.')
flow('Tespitten sonra uçuş ne yaptı?','İlk olaydan yaklaşık317s sonra AUTO iniş tamamlandı.',[
 ('Olay','AUTO10 · NAV3'),('Tarama','Kalan sabit bacaklar'),('Yaklaşma','Önceden yüklü iniş bölümü'),('Bitiş','LAND → disarm')],
 'Bu süre olayın gerçekten üretildiği duvar saati ile auto_landed olayının duvar saati arasından hesaplandı:317,05s. Böylece yalnız daha sonra kayıttan işlenmiş bir görüntüyü canlıymış gibi sunmuyoruz. Aynı süre boyunca kayıtlı silahlı uçuş modu10AUTOolarak kaldı. Görüntü işçisinin gönderdiği uçuş komutu sayısı sıfırdır. Uygulamanın başarısı tespit kutusu yanında görevin kesilmeden tamamlanmasıyla ölçülür.')
cards('Uygulama: alarmı üret, rotayı koru','Öğrenciden hem görüntü olayı hem AUTO devam kanıtı isteyin.',[
 ('Başlat','Menü4 → görev dosyasını araca yaz.'),('Gözle','products/motion altında olay oluşsun.'),('Kanıtla','Olaydan sonra AUTO sürsün; LAND ve disarm gelsin.')],
 'Öğrenci menüsü4sabit kanat görüntü işçisini otomatik açar. Başlatıcı uçuşu başlatmaz; Mission Planner operatörü görevi yazar ve AUTOarm yapar. Görev bitince events.jsonl dosyasındaki kaynak görev indeksi ve mod bilgisi incelenir. Bir doğru olay ve bir yanlış alarmı rapora eklemelerini isteyin. Algılanan hedefe gitmek için waypoint değiştirmek bu haftanın kapsamındaki görevi bozar. Rotanın sabit kalması bilinçli başarı koşuludur.')

SEC='SONUÇLARI ÜRETME VE DEĞERLENDİRME'
table('Dosyaları nerede bulacağız?','Görev, kaynak dünya ve ürünler ayrı dosyalarda tutulur.',
 ['Klasör / dosya','İçerik','Öğrencinin işi'],[
 ['missions/','Beş .waypoints + okunabilir JSON','Doğru görevi açıp araca yaz'],['worlds/ · models/','Üç dünya + yerel3Dvarlıklar','Menüyle doğru dünyayı aç'],['params/','Doğrulanan araç/kamera ayarları','Anlamını oku; rastgele değiştirme'],['.local/runs/','Kendi uçuşun: RGB + telemetri','RESULT yolunu sakla'],['products/','Mozaik · PLY · hareket olayları','Sonucu incele ve raporla']],
 'Görev dosyaları küçük metin dosyalarıdır; zip veya hazır uygulama paketi değildir. Yerel derleme ve kayıtlar .local altında kalır, GitHub’a yüklenmez. Paylaşılan örnek görseller sunum/gorseller içinde köken listesiyle bulunur. Öğrencilerin kendi çalışmasını teslim ederken tümham kareleri eklemek yerine görev değişikliği, metrik dosyası ve temsilî görüntüler seçmesi yeterlidir. Dosya adı ile uygulama adını eşleştirme alışkanlığını kazandırın.',sources=['repo'])
code('Her uçuş için aynı doğrulama komutu','Uçuş modu, iniş ve uygulama ölçümlerini raporlayın.',
 '.\\.local\\venv\\Scripts\\python.exe .\\tools\\report_run.py\n  "UCUS_KLASORU"',
 [('Ortak kontrol','AUTO · disarm · force-arm yok · setpoint yok.'),('Uygulamaya özel','İlaçlama kaplama; bina ROI hatası; uçuş grafikleri.')],
 'Komut terminalde tek satırdır. Rapor gerçek telemetriden uçuş izini ve irtifa profilini çizer. İlaçlamada pompa PWM’inden ideal kaplama üretir; bina uçuşunda gerçek kamera pozundan ROI doğrultu hatasını hesaplar. İlaçlama kaplaması95yüzdenin altındaysa veya bina ROI yüzde95hatası5dereceden büyükse doğrulama hata verir. Bu eşikler öğretim dünyasına aittir. Salt gözlemci logunda uçuş komutu listesi boş olmalıdır; öğretmen otomasyonunda arm/start görülebilir.')
table('Son denemeler: ne doğrulandı?','Sunum, çalışan son kayıtlar hazır olduktan sonra üretildi.',
 ['Uygulama','Uçuş sonucu','Ürün / ölçüm'],[
 ['Araç / kamera','AUTO ·8m · LAND','Üç gimbal açısı; pasif gözlemci'],['İlaçlama','AUTO ·4m · LAND','9aç/kapa · ideal kaplama%100'],['2D tarla','AUTO ·18m · LAND','81fotoğraf · alan%100'],['3D bina','AUTO ·18/23m · LAND','108fotoğraf ·1787nokta'],['Sabit kanat','AUTO kalkış ve iniş','Canlı23olay ·19kişi örtüşmesi']],
 'Tüm sonuçlar27Ekim2026tarihinde aynı native Windows ortamında kaydedildi. İniş başarısı disarm ve yere yakın irtifa ile doğrulanır. Sunumdaki sayılar tek örnek dünya ve kayıt ailesine aittir; farklı bilgisayar zamanlaması veya görev değişikliğiyle birebir aynı sayılar beklenmeyebilir. Beklenen nitel sonuçlar korunmalıdır: doğru AUTO rota, gerçek RGB veri, uygulama çıktısı ve açık sınırlamalar. Detaylı metrikler dogrulama/final_summary.json dosyasındadır.')
table('Bir hata → bir düzeltme → yeniden test','İterasyon, simülasyon hazırlığının bir parçasıdır.',
 ['Gözlenen sorun','Düzeltme','Kontrol'],[
 ['DO komutu geç çalıştı','Gereksiz mesafe koşulu kaldırıldı','Pompa / kamera zaman kaydı'],['Tarla kenarı eksik kaldı','9şerit ve uzatılmış uçlar','%82,86 →%100 ideal kaplama'],['Zemin ayrıntısı azdı','Kamera ayarı + ORB FAST3','Eşleşme ve gerçek olay'],['Dönüşte yanlış alarm','SCAN fazında işleme','Canlı olay + yanlış alarm sayısı'],['Kalkış yer koşusu zayıftı','İdeal iniş takımı ve ayarlar','AUTO kalkıştan disarm’a uçuş']],
 'Bu tablo denemelerin neden yalnız bir kez açıp kapatma olmadığını gösterir. Her düzeltme gözlenen bir soruna karşı yapılır ve farklı bir kanıtla doğrulanır. Bir düzenleme yeni sorun çıkarabilir; örneğin daha hassas ORB eşiği daha fazla gürültü getirebilir. Görüntü kalitesi, geometri, görev zamanlaması ve fizik birlikte değerlendirilir. Öğrenciler kendi raporlarında en az bir başarısız gözlem ve onu sınayan düzeltmeyi yazmalıdır.')
cards('AUTO ile bu hafta nereye kadar geldik?','Kalkıştan inişe görev ve faydalı yük kontrolü AUTO içinde kaldı.',[
 ('Planlı görev','Grid, orbit, sabit tarama, hız ve iniş.'),('Faydalı yük','Kamera mesafesi, ROI, gimbal ve sprayer.'),('Veri ürünü','Uçuş dışında veya eşzamanlı görüntü işleme.')],
 'Öğrencinin ana kazanımı Python yazmadan da ArduPilot görev motoruyla kapsamlı işler yapılabileceğini görmesidir. Python bu örneklerde veri işleme ve tekrarlanabilir ölçüm içindir. Hedef tespitiyle rotanın yeniden planlanması, dinamik engel kaçınma veya görsel servo bu haftada yapılmadı. Bu sınır, AUTO’nun güçlü olduğu öngörülebilir planlı görevleri net anlamaya yardımcı olur. Gelecek derslerde daha etkileşimli kontrolü karşılaştırmak için sağlam bir referansımız oluşur.',sources=['auto','commands'])
cards('Teslim: sonucu kanıtlayan kısa bir rapor','Görev dosyası + uçuş kanıtı + ürün + sınırlama yeterlidir.',[
 ('1 · Görev','Uygulama adı ve değiştirdiğin tek parametre.'),('2 · Uçuş','AUTO rota/irtifa grafiği ve iniş sonucu.'),('3 · Ürün','Bir çıktı görseli ve sayısal ölçüm.'),('4 · Yorum','Bir hata, düzeltme ve sonucun sınırı.')],
 'Tüm ham videoyu veya binlerce kareyi teslim istemek yerine kısa ve ölçülebilir rapor isteyin. İlaçlamada kaplama ve PWM; haritalamada fotoğraf sayısı ve mozaik; binada yönelim ve seyrek bulut; sabit kanatta bir doğru olay, bir yanlış alarm ve uçuş devam kanıtı seçilebilir. Tek bir başarılı ekran görüntüsü yeterli değildir. Öğrencinin sonuç için doğru terimi seçmesi değerlendirmeye dahildir: nominal GSD, ideal kaplama, seyrek bulut ve hareket adayı.')
cards('Ders sonunda üç kontrol sorusu','Bir sonucun neyi kanıtladığını ve neyi ölçmediğini açıklayın.',[
 ('Görev','DO komutu listede var ama çıkış yok: neden?'),('Geometri','İyi GSD neden iyi konum doğruluğu değildir?'),('Algılama','Hareketli kutu neden “insan tespiti” sayılmaz?')],
 'İlk soruda aktif NAV ve CONDITION zamanlaması, sonraki NAV’a geçiş ve çıkış parametreleri beklenir. İkinci soruda piksel örneklemesi ile kalibrasyon, poz ve kontrol noktası doğruluğu ayrımı beklenir. Üçüncü soruda hareket telafisi artığı, parallax, yanlış alarm ve sınıflandırıcının yokluğu tartışılır. Cevapların simülasyondaki gerçek örneklere bağlanmasını isteyin. Dersin amacı komut isimlerini ezberlemekten çok doğru başarı ölçütünü seçmektir.')
table('Kaynaklar ve yeniden çalışma','Resmî dokümanlar ile ders dosyaları birlikte okunabilir.',
 ['Konu','Resmî kaynak / ders kaynağı'],[
 ['AUTO ve görev komutları','ardupilot.org → Copter → AUTO / Mission commands'],['Grid, kamera, gimbal, sprayer','ardupilot.org → Mission Planner / Common topics'],['Sabit kanat kalkış ve iniş','ardupilot.org → Plane → Automatic takeoff / landing'],['Görüntü geometrisi','docs.opencv.org · colmap.github.io/tutorial.html'],['Bu haftanın tüm dosyaları','github.com/esrefsamilzamanoglu/uav-course → haftalar/02']],
 'Tıklanabilir tam adresler bu slaydın konuşmacı notlarında, sunumun kaynak dosyasında ve KAYNAKLAR.md belgesinde bulunur. Kaynaklar teknik davranışı destekler; sunumdaki başarı sayıları kendi simülasyon kayıtlarımızdan gelir. Kamuya açık depoda görevler, dünyalar, modeller, çalıştırıcılar, kaynak kod ve doğrulama özeti birlikte paylaşılır. İlk haftanın materyali aynı haftalık indeks içinde korunur. Bu haftayı yeniden çalışırken önce referans görevi değiştirmeden uçurun, sonra bir değişkeni değiştirin.',sources=list(SOURCES))

